// Runnable demo: at-most-once, at-least-once, exactly-once under a crash.
package com.bank.semantics.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class SemanticsDemo {
    private static final Logger log = Logger.getLogger(SemanticsDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Message m = new Message("TXF-1", "SAV2001", new BigDecimal("50000"));

        // AT-MOST-ONCE: commit BEFORE processing -> crash loses the message
        AtMostOnceConsumer amo = new AtMostOnceConsumer();
        amo.consumeWithCrash(m);

        // AT-LEAST-ONCE: process THEN commit -> crash causes redelivery (duplicate)
        AtLeastOnceConsumer alo = new AtLeastOnceConsumer();
        alo.consumeWithCrash(m);
        alo.consumeAgainAfterRestart(m); // redelivered

        // EXACTLY-ONCE (effectively): at-least-once + idempotent guard -> no duplicate effect
        ExactlyOnceConsumer eo = new ExactlyOnceConsumer();
        eo.consumeWithCrash(m);
        eo.consumeAgainAfterRestart(m); // redelivered but ignored
    }
}

// ─── Would be in Message.java ───
class Message {
    private final String id, accountId;
    private final BigDecimal amount;
    Message(String id, String accountId, BigDecimal amount) {
        this.id = id; this.accountId = accountId; this.amount = amount;
    }
    String getId() { return id; }
    String getAccountId() { return accountId; }
    BigDecimal getAmount() { return amount; }
    @Override public String toString() { return id + " " + accountId + " " + amount; }
}

// ─── Would be in AtMostOnceConsumer.java ───
class AtMostOnceConsumer {
    private static final Logger log = Logger.getLogger(AtMostOnceConsumer.class.getName());
    // Commit offset FIRST; if we crash before processing, the message is LOST
    void consumeWithCrash(Message m) {
        log.info(() -> "[at-most-once] commit offset for " + m.getId() + " (before processing)");
        boolean crashed = true; // simulate crash right after commit
        if (crashed) {
            log.severe(() -> "[at-most-once] CRASH before processing " + m.getId()
                    + " -> message LOST (never reprocessed)");
            return;
        }
        log.info(() -> "[at-most-once] processed " + m);
    }
}

// ─── Would be in AtLeastOnceConsumer.java ───
class AtLeastOnceConsumer {
    private static final Logger log = Logger.getLogger(AtLeastOnceConsumer.class.getName());
    // Process FIRST, commit AFTER; crash between the two causes redelivery
    void consumeWithCrash(Message m) {
        log.info(() -> "[at-least-once] processed " + m + " (debited " + m.getAccountId() + ")");
        boolean crashed = true; // simulate crash before commit
        if (crashed) {
            log.severe(() -> "[at-least-once] CRASH before commit " + m.getId()
                    + " -> will be REDELIVERED (duplicate)");
        }
    }
    void consumeAgainAfterRestart(Message m) {
        log.warning(() -> "[at-least-once] REDELIVERED " + m
                + " -> processed AGAIN (DUPLICATE debit!)");
    }
}

// ─── Would be in ExactlyOnceConsumer.java ───
class ExactlyOnceConsumer {
    private static final Logger log = Logger.getLogger(ExactlyOnceConsumer.class.getName());
    private final Set<String> processedIds = new HashSet<>(); // idempotency (DB unique in prod)
    void consumeWithCrash(Message m) {
        if (!processedIds.add(m.getId())) {
            log.warning(() -> "[exactly-once] " + m.getId() + " already processed — IGNORE");
            return;
        }
        log.info(() -> "[exactly-once] processed " + m + " (debited once)");
        boolean crashed = true; // crash before commit, like at-least-once
        if (crashed) log.severe(() -> "[exactly-once] CRASH before commit -> will be redelivered");
    }
    void consumeAgainAfterRestart(Message m) {
        if (!processedIds.add(m.getId())) {
            log.info(() -> "[exactly-once] REDELIVERED " + m.getId()
                    + " -> idempotent guard IGNORES it -> NO duplicate effect");
            return;
        }
        log.info(() -> "[exactly-once] processed " + m);
    }
}

